<template>
  <view class="page"><view v-if="orderId" class="tip">订单 {{ orderId }} · 退款申请提交后进入管理员审批，审批通过后执行退款</view><view class="card"><view class="row"><text class="type">{{ typeText }}</text><text class="status">提交申请</text></view><textarea v-model="reason" maxlength="200" class="reason-input" placeholder="请输入退款原因（选填）"/><button class="submit" :class="{ disabled: submitting }" @tap="submit">{{ submitting ? '提交中...' : '提交申请' }}</button></view><view class="tip">历史申请记录</view><view v-if="loading" class="tip">加载中...</view><view v-else-if="records.length"><view v-for="item in records" :key="item.id" class="card"><view class="row"><text class="type">{{ item.type }}</text><text class="status">{{ item.status }}</text></view><text class="reason">原因：{{ item.reason }}</text><view class="row"><text class="time">{{ item.createdAt }}</text><text class="amount">¥{{ item.amount }}</text></view></view></view><view v-else class="tip">暂无申请记录</view></view>
</template>
<script>
import api from '../../common/api.js'
const textFor = value => ({ pending_review: '待审批', approved: '审批通过', rejected: '已驳回', processing: '退款处理中', refunded: '已退款' })[value] || value || '未知状态'
export default { data() { return { orderId: '', backend: 'cloud', type: 'refund', typeText: '仅退款', reason: '', records: [], loading: true, submitting: false } }, onLoad(options) { this.orderId = options.orderId ? String(options.orderId) : ''; this.backend = options.backend === 'target' ? 'target' : 'cloud'; this.type = options.type === 'aftersale' ? 'aftersale' : 'refund'; this.typeText = this.type === 'aftersale' ? '售后申请' : '仅退款'; this.load() }, methods: { async load() { if (!this.orderId) { this.loading = false; return } this.loading = true; try { const rows = await api.getRefundRequestList(this.orderId, this.backend); this.records = api.asList(rows).map(item => ({ id: item.id, type: item.request_type === 'aftersale' ? '售后申请' : '仅退款', reason: item.reason || '—', amount: item.requested_amount || '0.00', status: textFor(item.status), createdAt: item.created_at || '' })) } catch (error) { uni.showToast({ title: error.message || '加载失败', icon: 'none' }) } finally { this.loading = false } }, async submit() { if (!this.orderId) return uni.showToast({ title: '缺少订单号', icon: 'none' }); if (this.type !== 'refund') return uni.showToast({ title: '售后申请接口预留中', icon: 'none' }); if (this.submitting) return; this.submitting = true; try { await api.applyRefundRequest({ orderId: this.orderId, backend: this.backend, reason: this.reason || '用户申请退款', refundType: 'refund_only' }); uni.showToast({ title: '已提交，待管理员审批', icon: 'none' }); setTimeout(() => uni.navigateBack(), 450) } catch (error) { uni.showToast({ title: error.message || '提交失败', icon: 'none' }) } finally { this.submitting = false } } } }
</script>
<style>
.page{min-height:100vh;padding:10px;box-sizing:border-box;background:#F4F6F8}.tip{padding:0 4px 8px;color:#636366;font-size:12px;line-height:1.5}.card{margin-bottom:10px;padding:13px;border-radius:8px;background:#fff}.row{display:flex;align-items:center;justify-content:space-between}.type{font-size:14px;font-weight:650}.status{color:#0B0D10;font-size:12px;font-weight:650}.reason-input{width:100%;height:70px;margin-top:10px;padding:8px;box-sizing:border-box;border-radius:6px;background:#f8f8f8;font-size:12px}.submit{margin-top:10px;border-radius:19px;background:#0B0D10;color:#fff;font-size:13px;line-height:38px}.submit::after{border:0}.submit.disabled{opacity:.6}.reason{display:block;margin:8px 0;font-size:12px;color:#666}.time{font-size:11px;color:#8e8e93}.amount{font-size:13px;font-weight:650}
</style>
